/* Owner payment configuration and manual deposit evidence preview; no external payment calls. */
const paymentKinds=['Bank transfer','Easypaisa','JazzCash','Cash at venue','Other'];
const paymentIcons={'Bank transfer':'wallet',Easypaisa:'wallet',JazzCash:'wallet','Cash at venue':'wallet',Other:'wallet'};
function paymentAccount(type,enabled=false){return {id:'PAY-'+Date.now()+'-'+Math.random().toString(36).slice(2,7),type,label:type,enabled,online:enabled&&type!=='Cash at venue',title:'Demo Venue',institution:type==='Bank transfer'?'Demo Bank':'',number:type==='Bank transfer'?'DEMO-ACCOUNT-001':type==='Cash at venue'?'':'DEMO-WALLET',notes:type==='Cash at venue'?'Visit the venue reception to pay.':'Use the booking reference in your payment note.'}}
function paymentSettings(){let c=installState.config;if(!c.paymentSettings){let old=c.venue6||{};c.paymentSettings={deposit:old.v0??5,accounts:[paymentAccount('Bank transfer',true),paymentAccount('Easypaisa'),paymentAccount('JazzCash'),paymentAccount('Cash at venue',true)]};persistInstall()}return c.paymentSettings}
let paymentDraft=null,paymentChoice='';
const paymentWizard=()=>mode==='install'&&page==='start'&&installState.stage===5&&setupStep===6;
const editingPayments=()=>paymentWizard()?paymentSettings():(paymentDraft||(paymentDraft=JSON.parse(JSON.stringify(paymentSettings()))));
const onlineAccounts=()=>paymentSettings().accounts.filter(a=>a.enabled&&a.online);
const staffAccounts=()=>paymentSettings().accounts.filter(a=>a.enabled);
function payInput(label,name,value,type='text',required=true,extra=''){return `<label class="field">${esc(label)}<input name="${esc(name)}" type="${type}" value="${esc(value??'')}" ${required?'required':''} ${extra}></label>`}
function payCheckbox(name,label,checked,disabled=false){return `<label class="pay-check"><input type="checkbox" name="${name}" ${checked?'checked':''} ${disabled?'disabled':''}>${esc(label)}</label>`}
function paymentEditor(s){return `<section class="config-card pay-deposit"><div class="config-intro"><div><h3>Booking deposit</h3><p>Set the percentage required to reserve an event. A 0% deposit means no advance payment is required.</p></div></div>${payInput('Deposit percentage (%)','pay-deposit',s.deposit,'number',true,'min="0" max="100" step="0.01"')}</section><div class="config-intro" style="margin-top:20px"><div><h3>How do customers pay you?</h3><p>Enable the receiving methods you accept. Add multiple accounts of the same type if needed.</p></div><span class="config-count">${countLabel(s.accounts.filter(a=>a.enabled).length,'active method')}</span></div><div class="config-stack">${s.accounts.map((a,i)=>`<section class="config-card pay-card ${a.enabled?'':'pay-off'}"><div class="config-card-head"><div class="pay-method-icon ${a.type==='Easypaisa'?'easy':a.type==='JazzCash'?'jazz':'bank'}">${a.type==='Easypaisa'?'EP':a.type==='JazzCash'?'JC':ic(paymentIcons[a.type])}</div><div><h3>${esc(a.label||a.type)}</h3><small>${esc(a.type)} · ${a.enabled?'Enabled':'Disabled'}</small></div>${cfgButton('Remove','pay-remove:'+i,'danger sm')}</div><div class="pay-toggles">${payCheckbox('pay-'+i+'-enabled','Accept this payment method',a.enabled)}${payCheckbox('pay-'+i+'-online','Show in online booking',a.online&&a.enabled,!a.enabled)}</div>${a.enabled?`<div class="fields">${payInput('Display label','pay-'+i+'-label',a.label)}${a.type==='Cash at venue'?payInput('Receiving location','pay-'+i+'-title',a.title||'Venue reception'):payInput('Account holder / account title','pay-'+i+'-title',a.title)}${a.type==='Bank transfer'?payInput('Bank name','pay-'+i+'-institution',a.institution):''}${a.type!=='Cash at venue'?payInput(a.type==='Bank transfer'?'Account number / IBAN':'Wallet / receiving account number','pay-'+i+'-number',a.number):''}<label class="field span2">Payment instructions<textarea name="pay-${i}-notes" placeholder="Optional instructions">${esc(a.notes)}</textarea></label></div><div class="pay-account-note">${a.type==='Cash at venue'?'Staff records cash received in person. A public cash request does not confirm payment.':'Manual transfer: transaction reference and evidence are reviewed before confirming a deposit.'}</div>`:'<p class="muted config-help">Enable this method to configure its receiving details.</p>'}</section>`).join('')}</div><div class="pay-add"><label class="field">Add a receiving method<select id="pay-new-type">${paymentKinds.map(t=>`<option>${t}</option>`).join('')}</select></label>${cfgButton('Add account','pay-add','primary','plus')}</div><div class="note"><b>Mock data only.</b> Do not enter real bank or wallet credentials, PINs, passwords, or OTPs. Live gateway integration is a separate secure configuration.</div>`}
function validatePaymentSettings(s){let d=Number(s.deposit);if(String(s.deposit).trim()===''||!Number.isFinite(d)||d<0||d>100)return 'Deposit percentage must be between 0 and 100.';let names=new Set;for(const a of s.accounts){if(!a.enabled)continue;let label=a.label.trim().toLowerCase();if(!label||!a.title.trim())return 'Enter a display label and account title or receiving location for every enabled method.';if(names.has(label))return 'Use a different display label for each enabled account.';names.add(label);if(a.type==='Bank transfer'&&!a.institution.trim())return 'Enter a bank name.';if(a.type!=='Cash at venue'&&!a.number.trim())return 'Enter an account number or wallet number.'}return ''}
function savePaymentSettings(s){installState.config.paymentSettings=JSON.parse(JSON.stringify(s));installState.config.venue6={...(installState.config.venue6||{}),v0:s.deposit,v1:'Configured accounts',v2:'PKR'};persistInstall()}
const payOldFormFields=formFields;
formFields=function(fs){return paymentWizard()?paymentEditor(editingPayments()):payOldFormFields(fs)};
const payOldAdvanceVenue=advanceVenue;
advanceVenue=function(fd){if(setupStep===6){let s=editingPayments(),err=validatePaymentSettings(s);if(err)return installFail(err);savePaymentSettings(s);fd={v0:s.deposit,v1:'Configured accounts',v2:'PKR'}}return payOldAdvanceVenue(fd)};
venueDefs.paymentMethods=def('Payment methods','Configure receiving accounts and booking deposits.','wallet',[],[],[],'');
ownerGroups.find(g=>g[0]==='Manage your business')[1].splice(3,0,['paymentMethods','Payment methods','wallet']);
const payOldGeneric=generic;
generic=function(c,key){if(key!=='venue-paymentMethods')return payOldGeneric(c,key);let s=editingPayments();return pagehead('Payment methods','Configure where your customers send payments, and what appears in online booking.',btn('View payment evidence','go:paymentClaims','outline','shield'))+metrics([['Enabled methods',String(s.accounts.filter(a=>a.enabled).length),'wallet'],['Shown on website',String(s.accounts.filter(a=>a.enabled&&a.online).length),'globe'],['Booking deposit',s.deposit+'%','check'],['Verification','Manual review','shield']])+`<form id="payment-settings-form">${card('Receiving accounts',paymentEditor(s))}<div class="actions">${cfgButton('Discard changes','pay-discard','outline')}<button type="submit" class="btn gold">Save payment methods</button></div></form>`};
function paymentClaims(){return rows('venue-payment-claims',[])}
venueDefs.paymentClaims=def('Payment evidence','Review manually submitted deposits and payment references.','shield',[],[],[],'');
ownerGroups.find(g=>g[0]==='More booking tools')[1].push(['paymentClaims','Payment evidence','shield']);
const paySettingsGeneric=generic;
generic=function(c,key){if(key!=='venue-paymentClaims')return paySettingsGeneric(c,key);return pagehead('Payment evidence','Review transfer references before accepting a deposit.',btn('Payment methods','go:paymentMethods','outline','wallet'))+card('Submitted deposits',`<div class="note">This queue uses sample evidence. Approval here simulates a verified payment; no real settlement or accounting entry occurs.</div><div class="table-wrap"><table><thead><tr><th>Booking</th><th>Method</th><th>Amount</th><th>Reference</th><th>Status</th><th>Actions</th></tr></thead><tbody>${paymentClaims().map((r,i)=>`<tr><td>${esc(r.booking)}</td><td>${esc(r.method)}</td><td>${money(r.amount)}</td><td>${esc(r.reference)}</td><td>${badge(r.status)}</td><td>${r.status==='Pending review'?`<div class="actions">${cfgButton('Verify (demo)','pay-review:'+i+':verified','primary sm')}${cfgButton('Reject','pay-review:'+i+':rejected','danger sm')}</div>`:'Reviewed'}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No submitted payment evidence yet. Try a public booking.</td></tr>'}</tbody></table></div>`)};
const payOldAction=action;
action=function(a){if(!a.startsWith('pay-'))return payOldAction(a);let [kind,idx,value]=a.split(':');if(kind==='pay-review'){let r=paymentClaims()[+idx];if(!r||r.status!=='Pending review')return;r.status=value==='verified'?'Verified (demo)':'Rejected';for(let key of ['venue-reservations','venue-publicBookings']){let item=rows(key,initial.bookings).find(x=>x[0]===r.booking);if(item)item[5]=value==='verified'?'Confirmed':'Payment rejected'}save();render();return}if(kind==='pay-discard'){paymentDraft=null;render();return}let s=editingPayments();if(kind==='pay-add'){let type=$('#pay-new-type')?.value||'Bank transfer';let a=paymentAccount(type,true);a.label=type+' '+(s.accounts.filter(x=>x.type===type).length+1);s.accounts.push(a)}else if(kind==='pay-remove')s.accounts.splice(+idx,1);if(paymentWizard())persistInstall();render()};
function updatePaymentField(name,value){let s=editingPayments();if(name==='pay-deposit'){s.deposit=value;return true}let m=name.match(/^pay-(\d+)-(enabled|online|label|title|institution|number|notes)$/);if(!m||!s.accounts[+m[1]])return false;let a=s.accounts[+m[1]];a[m[2]]=value;if(m[2]==='enabled'&&!value)a.online=false;return true}
document.addEventListener('input',e=>{let n=e.target.name||'';if(!n.startsWith('pay-')||e.target.type==='checkbox')return;if(updatePaymentField(n,e.target.value)&&paymentWizard())persistInstall()},true);
document.addEventListener('change',e=>{let n=e.target.name||'';if(n.startsWith('pay-')&&e.target.type==='checkbox'){if(updatePaymentField(n,e.target.checked)){if(paymentWizard())persistInstall();render()}}else if(n==='booking-payment-account'){paymentChoice=e.target.value;render()}},true);
document.addEventListener('submit',e=>{if(e.target.id!=='payment-settings-form')return;e.preventDefault();e.stopImmediatePropagation();let s=editingPayments(),err=validatePaymentSettings(s);if(err){toast(err);return}savePaymentSettings(s);paymentDraft=null;render();toast('Payment methods saved in the mock.')},true);
const payOldFinance=finance;
finance=function(){let html=payOldFinance();return html.replace('</header>',`</header><div class="actions" style="margin-bottom:14px">${btn('Manage payment methods','go:paymentMethods','outline','wallet')}${btn('Review payment evidence','go:paymentClaims','outline','shield')}</div>`)};
const beforePayNewRecord=newRecord;
newRecord=function(key,index){if(key==='finance-1'){let f=financeConfigs[1].fields.find(x=>x.label==='Method'),opts=staffAccounts().map(a=>a.label);f.opts=opts;f.value=opts[0]||'';if(!opts.length){toast('Enable a receiving method first.');return}}beforePayNewRecord(key,index)};
function paymentBookingFields(deposit,publicMode){let opts=publicMode?onlineAccounts():staffAccounts();let a=opts.find(x=>x.id===paymentChoice)||opts[0];paymentChoice=a?.id||'';if(deposit===0)return '<div class="note">No deposit required. Submit your booking request for review.</div>';if(!a)return '<div class="note">Online deposits are not enabled. Submit a booking request and contact the venue to arrange payment.</div>';return `<div class="note"><b>Demo only:</b> Do not send money or enter real payment information. Bank and wallet transfers require review.</div><label class="field">Choose payment method<select name="booking-payment-account">${opts.map(x=>`<option value="${esc(x.id)}" ${x.id===a.id?'selected':''}>${esc(x.label)}</option>`).join('')}</select></label><section class="config-card" style="margin:14px 0"><h3>${esc(a.label)}</h3><div class="summary-lines"><div><span>${a.type==='Cash at venue'?'Receiving location':'Account holder'}</span><b>${esc(a.title)}</b></div>${a.type==='Bank transfer'?`<div><span>Bank</span><b>${esc(a.institution)}</b></div>`:''}${a.type!=='Cash at venue'?`<div><span>${a.type==='Bank transfer'?'Account / IBAN':'Wallet number'}</span><b>${esc(a.number)}</b></div>`:''}<div class="total"><span>Amount due</span><b>${money(deposit)}</b></div></div><p class="muted config-help">${esc(a.notes)}</p></section>${a.type==='Cash at venue'?'<div class="note">Pay at reception. A cash payment request is not proof of payment.</div>':`${payInput('Sample transaction reference','booking-payment-reference','DEMO-TXN-001')}<p class="muted config-help">A real application would accept private receipt evidence and independently verify settlement.</p>`}`}
function completeMockPayment(fd,h,publicMode){let s=paymentSettings(),amount=Math.round(+h.price*+s.deposit/100),opts=publicMode?onlineAccounts():staffAccounts(),a=opts.find(x=>x.id===fd['booking-payment-account']);if(amount>0&&opts.length&&!a){toast('Choose an available payment method.');return false}let ref=String(fd['booking-payment-reference']||'').trim();if(amount>0&&a&&a.type!=='Cash at venue'&&!ref){toast('Enter a sample transaction reference.');return false}booking.reference='DEMO-BK-'+Date.now().toString().slice(-6);booking.paymentStatus=amount===0?'Pending review':a&&a.type!=='Cash at venue'?'Payment pending review':'Awaiting deposit';let row=[booking.reference,booking.name,booking.date,h.name,booking.program,booking.paymentStatus,money(h.price)];rows('venue-reservations',initial.bookings).push(row);if(publicMode)rows('venue-publicBookings',initial.bookings).push([...row]);if(amount>0&&a&&a.type!=='Cash at venue')paymentClaims().push({booking:booking.reference,method:a.label,amount,reference:ref,status:'Pending review'});save();return true}
function paymentBookingConfirmation(h,p){return `<div style="text-align:center;padding:30px 8px"><div class="task-icon" style="margin:0 auto 14px">${ic('clock')}</div><h1 style="font-size:30px">Booking request submitted</h1><p style="margin:12px 0">${esc(h.name)} · ${esc(booking.date)} · ${esc(p.name)}</p>${badge(booking.paymentStatus||'Pending review')}<p style="margin:14px 0">Reference: ${esc(booking.reference||'DEMO-BK-0004')}</p><div class="note">Your booking will be confirmed only after the venue approves it and verifies any required deposit.</div>${btn('View booking status','route:public/status','primary')}</div>`}
const payOldBookingFlow=bookingFlow;
bookingFlow=function(isPublic){return payOldBookingFlow(isPublic).replace('Confirm synthetic deposit','Submit booking request')};
const paymentPublicPage=publicPage;
publicPage=function(){let html=paymentPublicPage();return page==='status'&&booking.reference?html.replace('value="DEMO-BK-0004"',`value="${esc(booking.reference)}"`):html};
document.addEventListener('submit',e=>{if(e.target.id!=='status-form')return;let fd=Object.fromEntries(new FormData(e.target)),r=rows('venue-reservations',initial.bookings).find(x=>x[0]===fd.reference);e.preventDefault();e.stopImmediatePropagation();$('#status-result').innerHTML=r?`<div class="record"><div><b>${esc(r[0])}</b><small>${esc(r[3])} · ${esc(r[2])}</small></div>${badge(r[5])}</div>`:'<div class="empty">No matching sample booking found.</div>'},true);
window.addEventListener('hashchange',()=>{paymentDraft=null;paymentChoice=''});paymentSettings();render();
